function test_lazyFetchDoS_emptyWhitelistBlocking() public {
    // Setup: registry has token with pairedTokenWhitelistId=5, list 5 has [WETH]
    // Hook is NOT in hooksToSync during setTokenSettings call
    // Hook local _tokenSettings[token].initialized == false
    // Hook local _pairTokenWhitelists[5] == empty
    vm.prank(address(amm));
    HookSwapParams memory params = HookSwapParams({
        tokenIn: token, tokenOut: WETH, poolId: bytes32(0),
        hookForInputToken: true, inputSwap: true, amount: 1e18
    });
    vm.expectRevert(AMMStandardHook__PairNotAllowed.selector);
    hook.beforeSwap(context, params, "");
    // Assert: swap blocked even though WETH is in registry's whitelist 5
}

function test_initializedFalse_triggersReloadWithEmptyWhitelist() public {
    // Whitelist 6 exists in registry (empty) but was never synced to hook
    uint256 listId = 6;
    HookTokenSettings memory newSettings = HookTokenSettings({
        initialized: false, // key: caller sets false
        pairedTokenWhitelistId: uint56(listId),
        tradingIsPaused: false,
        blockDirectSwaps: false,
        checkDisabledPools: false,
        tokenFeeBuyBPS: 0, tokenFeeSellBPS: 0,
        pairedFeeBuyBPS: 0, pairedFeeSellBPS: 0,
        minFeeAmount: 0, maxFeeAmount: 0,
        lpWhitelistId: 0, poolTypeWhitelistId: 0
    });
    address[] memory hooks = new address[](1);
    hooks[0] = address(hook);
    vm.prank(tokenOwner);
    registry.setTokenSettings(token, newSettings,
        new bytes32[](0), new bytes[](0), new bytes32[](0), new bytes32[](0), hooks);
    // Hook now has initialized=false, pairedTokenWhitelistId=6, _pairTokenWhitelists[6] is empty
    // Next swap triggers re-fetch -> gets pairedTokenWhitelistId=6 but contents empty
    vm.prank(address(amm));
    vm.expectRevert(AMMStandardHook__PairNotAllowed.selector);
    hook.beforeSwap(context, swapParamsWithWETH, "");
}

function test_priceBoundsNotSynced_swapBypassesBounds() public {
    // Registry has min/max sqrtPrice bounds for tokenA/WETH
    // Hook was added AFTER setPricingBounds with hooksToSync=[]
    PricingBounds memory regBounds = registry.getPriceBounds(tokenA, WETH);
    assertTrue(regBounds.isSet, "registry bounds must be set");
    // Hook has no bounds for tokenA/WETH
    // Manipulate pool price to 2x the registry maximum
    // Execute swap — hook should revert but doesn't due to isSet=false
    vm.prank(address(amm));
    // passes without revert even at extreme price
    uint256 fee = hook.beforeSwap(context, swapParamsAtExtremePrice, "");
    assertGe(fee, 0, "bounds bypass confirmed — no revert at extreme price");
}

function test_handlerOrderBypassesStaleBounds() public {
    // Registry has strict bounds: price of tokenA in WETH must be in [P_MIN, P_MAX]
    // Hook has _pricingBounds[tokenA][WETH].isSet == false (never synced)
    uint256 amountIn  = 1e18;  // 1 tokenA
    uint256 amountOut = 1;     // 1 wei WETH — effectively zero price
    // price = computeRatioX96(amountOut, amountIn) << P_MIN
    // Should revert if bounds were synced, but bounds.isSet=false silently skips check
    address clobHandler = makeAddr("clobHandler");
    vm.prank(clobHandler);
    hook.validateHandlerOrder(
        makeAddr("maker"), true, tokenA, WETH,
        amountIn, amountOut, "", ""
    );
    // No revert — order at near-zero price accepted
    // When order fills, maker gets 1 tokenA for 1 wei WETH
}

function test_bannedLP_continuesLiquidityViaStaleHookCache() public {
    address alice = makeAddr("alice");
    // alice is in hook's local _lpWhitelists[listId]
    assertTrue(hook.isWhitelistedLiquidityProvider(listId, alice));
    // Whitelist owner bans alice in registry but does NOT sync hook
    address[] memory toRemove = new address[](1);
    toRemove[0] = alice;
    vm.prank(whitelistOwner);
    registry.updateLpWhitelist(listId, toRemove, false, new address[](0));
    // Registry removed alice; hook still has her
    assertFalse(registry.isWhitelistedLp(listId, alice));
    assertTrue(hook.isWhitelistedLiquidityProvider(listId, alice));
    // Alice adds liquidity — hook checks LOCAL cache -> still whitelisted
    LiquidityContext memory ctx;
    ctx.provider = alice;
    vm.prank(address(amm));
    (uint256 f0, uint256 f1) = hook.validateAddLiquidity(
        true, ctx, liquidityParams, 1e18, 1e18, 0, 0, ""
    );
    // No revert — alice still adds liquidity despite registry ban
    assertEq(f0, 0);
}

function test_poolDisable_ignored_when_checkDisabledPools_false() public {
    // Setup: hook's cached tokenSettings.checkDisabledPools == false
    // Token admin emergency-disables pool in registry
    vm.prank(tokenOwner);
    registry.setPoolDisabled(token, poolId, true);
    assertTrue(registry.isPoolDisabled(poolId), "pool should be disabled in registry");
    // Swap proceeds through hook — _checkPoolEnabled sees checkDisabledPools=false
    // so never calls SETTINGS_REGISTRY.isPoolDisabled
    vm.prank(address(amm));
    uint256 fee = hook.beforeSwap(context, swapParams, "");
    // No PoolDisabled revert — emergency disable is silently ignored
    assertGe(fee, 0, "swap succeeded despite pool being disabled");
}

function test_directSwap_noDirectionExemption_blocksCorrectiveTrade() public {
    // Setup: token has minSqrtPriceX96=P_MIN, bounds synced to hook
    // Current pool price has drifted below P_MIN (token undervalued)
    // A corrective direct swap buys tokenA (raises price toward P_MIN)
    // For a pool swap with direction not-zero-for-one, line 858 would NOT revert
    // For a direct swap, poolType==address(0) forces strict revert on line 859
    vm.startPrank(address(amm));
    // beforeSwap: stores input amount in TSTORE, no check yet
    hook.beforeSwap(context, directBuyTokenA, "");
    // afterSwap: computes price, finds sqrtPrice < minSqrtPriceX96
    // !zeroForOne (buying tokenA) would normally get direction exemption
    // but (zeroForOne || poolType==address(0)) = (false || true) = true -> REVERT
    vm.expectRevert(AMMStandardHook__InvalidPrice.selector);
    hook.afterSwap(context, directBuyTokenA, "");
    vm.stopPrank();
    // Corrective pool swap succeeds; corrective direct swap fails
    // Impact: price correction delayed; sustained IL for LPs
}
